sect3.programlisting:
notify 30 {
	match "system" "IFNET";
	match "subsystem" "carp0";
	match "type" "LINK_UP";
	action "/usr/local/sbin/carp-hast-switch master";
};

notify 30 {
	match "system" "IFNET";
	match "subsystem" "carp0";
	match "type" "LINK_DOWN";
	action "/usr/local/sbin/carp-hast-switch slave";
};

listitem.para:
Hoe de basisgereedschappen te gebruiken om de
	  verschillende RAID-niveaus in te stellen,
	  te onderhouden en te wijzigen;

Hoe schijfapparaten via GEOM te spiegelen, aaneen te
	  schakelen, te versleutelen en vanaf afstand schijven aan te
	  sluiten;

Nog beter, verspreid de bestandssystemen over
		  meerdere schijven via het apparaat ccd4
		  (concatenated disk driver);

step.para:
Voeg een regel aan /etc/ttys toe
	    voor de ingang in de map /dev voor een
	    seriële poort als deze er nog niet is;

listitem.para:
DTR geldt tijdens gebruik; het
	    loslaten van DTR hangt de verbinding op en stelt het modem
	    opnieuw in;

Elke regel nx= overeenkomt met een
	      naam van een andere specificatie in
	      gettytab;

step.para:
Verbind de seriële kabel met
	    COM1 en de leidende
	    terminal;

sect2.programlisting:
#!/bin/sh pgrep -l pppd pid=`pgrep pppd` if [ "X${pid}" != "X" ] ; then echo 'killing pppd, PID=' ${pid} kill ${pid} fi pgrep -l kermit pid=`pgrep kermit` if [ "X${pid}" != "X" ] ; then echo 'killing kermit, PID=' ${pid} kill -9 ${pid} fi
ifconfig ppp0 down ifconfig ppp0 delete
kermit -y /etc/ppp/kermit.dial pppd /dev/tty01 19200

#!/bin/sh
pid=`pgrep pppd`
if [ X${pid} != "X" ] ; then
        echo 'killing pppd, PID=' ${pid}
        kill -TERM ${pid}
fi

pgrep -l kermit
pid=`pgrep kermit`
if [ "X${pid}" != "X" ] ; then
        echo 'killing kermit, PID=' ${pid}
        kill -9 ${pid}
fi

/sbin/ifconfig ppp0 down
/sbin/ifconfig ppp0 delete
kermit -y /etc/ppp/kermit.hup
/etc/ppp/ppptest

#!/bin/sh
pgrep -l pppd
pid=`pgrep pppd`
if [ "X${pid}" != "X" ] ; then
        echo 'killing pppd, PID=' ${pid}
        kill ${pid}
fi
pgrep -l kermit
pid=`pgrep kermit`
if [ "X${pid}" != "X" ] ; then
        echo 'killing kermit, PID=' ${pid}
        kill -9 ${pid}
fi
ifconfig ppp0 down
ifconfig ppp0 delete

kermit -y /etc/ppp/kermit.noans

